<?php
class FilaController extends BaseModuleController {
  public function dispatch(string $page): void { if($page==='fila-reprocessar') $this->reprocessar(); elseif($page==='fila-criar-teste') $this->criarTeste(); else $this->index(); }
  public static function routes(): array { return ['fila','fila-reprocessar','fila-criar-teste']; }
  public function index(): void { PermissionService::require('fila','visualizar'); $status=$_GET['status']??''; $sql='SELECT id,tipo,referencia,status,tentativas,proxima_tentativa,codigo_erro,trace_id,criado_em,atualizado_em FROM fila_integracao WHERE 1=1'; $params=[]; if($status){$sql.=' AND status=?';$params[]=$status;} $sql.=' ORDER BY id DESC LIMIT 200'; $st = TenantScopeService::run('fila_integracao', $sql, $params); $itens=$st->fetchAll(); $pageTitle='Fila de Integração'; $this->view('fila',compact('pageTitle','itens','status')); }
  public function reprocessar(): void { PermissionService::require('fila','reprocessar'); Csrf::validate(); $id=(int)($_POST['id']??0); if($id>0) QueueService::reprocessar($id); redirect('index.php?page=fila'); }
  public function criarTeste(): void { PermissionService::require('fila','reprocessar'); Csrf::validate(); $trace=RequestContext::id(); $referencia='BAIXA-TESTE-'.date('Ymd-His'); $payload=['referencia'=>$referencia,'origem'=>'tiny','evento'=>'baixa_estoque_teste','itens'=>[['sku'=>'TESTE001','quantidade'=>1,'descricao'=>'Produto Teste Hub de Integração','idProdutoTiny'=>'TESTE-TINY-001']],'observacao'=>'Teste Tiny → Hub → VSM','criado_em'=>date('c')]; $pdo=Database::forTable('fila_integracao'); $st=$pdo->prepare('INSERT INTO fila_integracao(tipo,referencia,payload,status,trace_id) VALUES(?,?,?,?,?)'); $st->execute(['baixa_estoque_vsm',$referencia,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'pendente',$trace]); Audit::event('fila.criar_baixa_teste','sucesso',['entidade'=>'fila_integracao','entidade_id'=>$pdo->lastInsertId(),'mensagem'=>'Baixa de estoque teste criada na fila.','payload'=>$payload]); redirect('index.php?page=fila&baixa_teste_criada=1'); }
}
